begin;
create extension if not exists pgtap with schema extensions;
-- Aislamiento transaccional: la eliminación se revierte al terminar el test.
delete from public.pvpc_days;
set local search_path=public,extensions;
select plan(12);
insert into auth.users(id,email,email_confirmed_at) values ('00000000-0000-0000-0000-000000000041','economy@example.invalid',now()),('00000000-0000-0000-0000-000000000042','outside@example.invalid',now());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000041',true);
set local role authenticated;
do $$begin perform set_config('test.economy_house',public.create_household('Económico')::text,true);end$$;
insert into public.appliances(id,household_id,name,duration_minutes,energy_kwh) values('00000000-0000-0000-0000-000000000051',current_setting('test.economy_house')::uuid,'Lavadora',120,2);
reset role;
insert into public.pvpc_days(id,date_local,source) values('00000000-0000-0000-0000-000000000061','2026-01-01','REData');
insert into public.pvpc_intervals(day_id,start_utc,end_utc,price_eur_kwh) select '00000000-0000-0000-0000-000000000061',t,t+interval '1 hour',0.1 from generate_series(date_trunc('hour',now())-interval '3 hours',date_trunc('hour',now())+interval '26 hours',interval '1 hour') t;
set local role authenticated;
do $$begin perform set_config('test.plan_start',(now()+interval '2 hour')::text,true);perform set_config('test.actual_start',(now()-interval '2 hours 5 minutes')::text,true);end$$;
reset role;update public.pvpc_days set validated_at=now()-interval '7 hours' where id='00000000-0000-0000-0000-000000000061';set local role authenticated;
select throws_ok($$select public.create_official_plan(current_setting('test.economy_house')::uuid,'00000000-0000-0000-0000-000000000051',current_setting('test.plan_start')::timestamptz,null)$$,null,null,'no se crea plan con precios actuales obsoletos');
reset role;update public.pvpc_days set validated_at=now() where id='00000000-0000-0000-0000-000000000061';set local role authenticated;
select lives_ok($$select public.create_official_plan(current_setting('test.economy_house')::uuid,'00000000-0000-0000-0000-000000000051',current_setting('test.plan_start')::timestamptz,'00000000-0000-0000-0000-000000000071')$$,'plan creado con cálculo del servidor');
select is((select (snapshot->>'cost')::numeric from public.plans where id='00000000-0000-0000-0000-000000000071'),0.2::numeric,'coste procede de precios y consumo oficiales');
select lives_ok($$select public.create_official_plan(current_setting('test.economy_house')::uuid,'00000000-0000-0000-0000-000000000051',current_setting('test.plan_start')::timestamptz,'00000000-0000-0000-0000-000000000071')$$,'reintento de creación idempotente');
select is((select count(*)::integer from public.plans),1,'sin plan duplicado');
select throws_ok($$update public.plans set snapshot='{"cost":"0"}'$$,'42501',null,'cliente no altera importes');
select throws_ok($$select public.confirm_official_plan('00000000-0000-0000-0000-000000000071',now()-interval '15 minutes')$$,null,null,'no confirma un ciclo que aún no ha terminado');
select lives_ok($$select public.confirm_official_plan('00000000-0000-0000-0000-000000000071',current_setting('test.actual_start')::timestamptz)$$,'confirmación calculada en servidor');
select is((select (snapshot->>'actualCost')::numeric from public.plans where id='00000000-0000-0000-0000-000000000071'),0.2::numeric,'coste confirmado recalculado');
select lives_ok($$select public.confirm_official_plan('00000000-0000-0000-0000-000000000071',current_setting('test.actual_start')::timestamptz)$$,'confirmación repetida idempotente');
select lives_ok($$select public.cancel_official_plan('00000000-0000-0000-0000-000000000071')$$,'anulación autorizada');
select throws_ok($$select public.create_official_plan(current_setting('test.economy_house')::uuid,'00000000-0000-0000-0000-000000000051',now()+interval '10 days',null)$$,null,null,'sin precios completos no se crea plan');
reset role;select * from finish();rollback;
